<?php
// Removes the "openapi: new OpenApiOperation(...)" argument blocks from operation attributes.
foreach (array_slice($argv, 1) as $file) {
    $lines = file($file);
    $out = [];
    $skip = false;
    $depth = 0;
    foreach ($lines as $line) {
        if (!$skip && preg_match('/^(\s*)openapi: new OpenApiOperation\($/', $line)) {
            $skip = true;
            $depth = 0;
            continue;
        }
        if ($skip) {
            if (preg_match('/^(\s*)\),$/', $line) && strlen(preg_replace('/\S.*/', '', $line)) === 12) {
                $skip = false;
            }
            continue;
        }
        $out[] = $line;
    }
    file_put_contents($file, implode('', $out));
}
